// spec: .qa/e2e/specs/prayer-mode.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

const PRAYER = 'shacharit_ashkenaz';
const TOTAL = 66;

type Section = { counter: string; text: string };

async function counterText(page: Page) {
  const body = await page.locator('body').innerText();
  return (body.match(/\d+ מתוך \d+/) ?? [''])[0];
}

async function goToFirst(page: Page) {
  const prev = page.getByText('קודם', { exact: true });
  for (let i = 0; i < TOTAL + 5; i++) {
    if ((await counterText(page)) === `1 מתוך ${TOTAL}`) break;
    await prev.click();
  }
  await expect(page.getByText(`1 מתוך ${TOTAL}`).first()).toBeVisible();
}

async function walk(page: Page): Promise<Section[]> {
  const result: Section[] = [];
  const next = page.getByText('המשך', { exact: true });
  for (let i = 1; i <= TOTAL; i++) {
    await expect(page.getByText(`${i} מתוך ${TOTAL}`).first()).toBeVisible();
    const text = await page.locator('body').innerText();
    result.push({ counter: `${i} מתוך ${TOTAL}`, text });
    // «סיים תפילה» есть на каждой секции (не нажимать)
    await expect(page.getByText('סיים תפילה', { exact: true })).toBeVisible();
    expect(text).not.toMatch(/נאמר רק במניין|יחיד מדלג/);
    // Нет отдельной секции «חזרת הש״ץ וקדושה» — קדושה внутри עמידה
    expect(text).not.toMatch(/^חזרת הש״ץ/m);
    if (i < TOTAL) {
      await next.click();
    } else {
      await expect(next).toHaveCount(0);
    }
  }
  return result;
}

test.describe('Режим молитвы «יחיד / מניין»', () => {
  test('PM-02 Содержание и счётчик одинаковы в «יחיד» и «מניין» — shacharit_ashkenaz #6a86f7e7 #6a86f7df @prod-safe @mobile', async ({ page }) => {
    // Длинный тест (66 секций × 2) — увеличенный timeout
    test.slow();

    const yachid = page.getByRole('radio', { name: 'יחיד' });
    const minyan = page.getByRole('radio', { name: 'מניין' });

    // 1. Открыть `/prayer/shacharit_ashkenaz`; нажимать «קודם», пока не будет «1 מתוך 66».
    await page.goto(`/prayer/${PRAYER}`);
    await expect(page.getByText(/\d+ מתוך \d+/).first()).toBeVisible();
    await goToFirst(page);

    // 2. Выбрать «יחיד».
    await yachid.click();
    await expect(yachid).toHaveAttribute('aria-checked', 'true');

    // 3. Нажимать «המשך» до «66 מתוך 66», на каждой секции записывая счётчик, заголовок и текст и проверяя наличие «סיים תפילה» (не нажимать).
    const individual = await walk(page);

    // 4. Нажимать «קודם» до «1 מתוך 66», выбрать «מניין».
    await goToFirst(page);
    await minyan.click();
    await expect(minyan).toHaveAttribute('aria-checked', 'true');
    await expect(yachid).toHaveAttribute('aria-checked', 'false');

    // 5. Повторить шаг 3.
    const congregation = await walk(page);

    // «1 מתוך 66» в обоих режимах; заголовки и тексты секций совпадают попарно
    expect(individual).toHaveLength(TOTAL);
    expect(congregation).toHaveLength(TOTAL);
    for (let i = 0; i < TOTAL; i++) {
      expect(congregation[i].counter).toBe(individual[i].counter);
      expect(congregation[i].text, `секция ${i + 1}`).toBe(individual[i].text);
    }

    // Вернуть режим «יחיד»
    await goToFirst(page);
    await yachid.click();
    await expect(yachid).toHaveAttribute('aria-checked', 'true');
    await expect(minyan).toHaveAttribute('aria-checked', 'false');
  });
});
